import Foundation

/// 公开摄像头索引（生成自 opencam.live 的公开地区页，2026-11-08）。
/// 只保存摄像头 ID 与公开坐标，不保存画面；每次取帧都实时向 opencam.live 的公开接口请求。
/// 坐标用于「换 IP 后自动选最近的摄像头」，无需联网查询目录。
struct LiveCamera {
    let id: String
    let name: String
    let region: String
    let latitude: Double
    let longitude: Double
    /// 名称指向山地 / 海岸 / 湖泊等自然景观，选点时给一点优先
    let natural: Bool
    var frameURL: URL? { URL(string: "https://opencam.live/api/cctv/frame/\(id)?size=full") }
    var pageURL: String { "https://opencam.live/globe?lat=\(latitude)&lng=\(longitude)&zoom=14&cam=\(id)" }
    var display: String { "\(region) · \(name)" }
}

