    /// 按大圆距离返回候选，自然风景类给最多 120km 的距离折扣。
    static func candidates(for place: Place, limit: Int = 10) -> [LiveCamera] {
        let scored = all.map { c -> (LiveCamera, Double) in
            let d = Self.km(place.latitude, place.longitude, c.latitude, c.longitude)
            return (c, d - (c.natural ? min(d * 0.3, 120) : 0))
        }.sorted { $0.1 < $1.1 }
        return Array(scored.prefix(limit).map { $0.0 })
    }

    static func byID(_ id: String) -> LiveCamera? { all.first { $0.id == id } }

    static func km(_ lat1: Double, _ lon1: Double, _ lat2: Double, _ lon2: Double) -> Double {
        let r = 6371.0, p = Double.pi / 180
        let a = sin((lat2 - lat1) * p / 2) * sin((lat2 - lat1) * p / 2)
            + cos(lat1 * p) * cos(lat2 * p)
            * sin((lon2 - lon1) * p / 2) * sin((lon2 - lon1) * p / 2)
        return r * 2 * atan2(sqrt(a), sqrt(1 - a))
    }
}
